public final class MainActivity extends Activity {
 boolean inQuiz=false; Engine engine; LinearLayout root,body,footer; android.graphics.Typeface regular,bold; MediaPlayer player;
 String screen="learn",search="",difficulty="All levels",origin="All sources",year="All years";int shown=100;
 final String[][] units={{"1","Introduction to Aerospace Technology"},{"2.1","The Atmospheric Flight Environment"},{"2.2","Design Concepts"},{"2.3","Aircraft Structures"},{"2.4","Fundamentals of Atmospheric Flight"},{"2.5","Propulsive Systems"}};
 final int GREEN=Color.rgb(88,204,2),INK=Color.rgb(60,60,60),GREY=Color.rgb(229,229,229),PURPLE=Color.rgb(133,73,186);
 interface Task{void run()throws Exception;}
 void attempt(Task task){try{task.run();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Could not finish this action").setMessage("Your last saved progress is retained. "+e.getClass().getSimpleName()).setPositiveButton("OK",null).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{regular=Typeface.createFromAsset(getAssets(),"fonts/duolingosans_regular.otf");bold=Typeface.createFromAsset(getAssets(),"fonts/duolingosans_bold.otf");engine=new Engine(this,"progress-v1.json");if(engine.session()!=null)quiz();else home();}catch(Exception e){TextView t=new TextView(this);t.setText("Unable to open the local course: "+e.getMessage());setContentView(t);}}
 int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 GradientDrawable bg(int fill,int border,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(2),border);return d;}
 TextView text(String value,int size,boolean strong){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(INK);t.setTypeface(strong?bold:regular);t.setLineSpacing(dp(3),1);t.setPadding(0,dp(6),0,dp(6));return t;}
 void add(LinearLayout parent,View child){parent.addView(child,new LinearLayout.LayoutParams(-1,-2));}
 Button button(String label,boolean primary,Task action){Button b=new Button(this);b.setText(label);b.setTextSize(16);b.setAllCaps(false);b.setTypeface(bold);b.setTextColor(primary?Color.WHITE:INK);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setMinHeight(dp(54));b.setBackground(bg(primary?GREEN:Color.WHITE,primary?0xff46a302:GREY,14));b.setStateListAnimator(null);b.setElevation(dp(primary?3:1));b.setOnClickListener(v->attempt(action));return b;}
 void spaced(LinearLayout parent,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));parent.addView(v,p);}
 void shell(){root=column();root.setBackgroundColor(Color.WHITE);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in;});setContentView(root);root.requestApplyInsets();}
 void scrollBody(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=column();body.setPadding(dp(22),dp(14),dp(22),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 void navigation(){LinearLayout nav=row();nav.setPadding(dp(6),dp(7),dp(6),dp(7));String[] names={"Learn","Mistakes","Questions","Settings"},ids={"learn","review","bank","settings"};for(int i=0;i<names.length;i++){final String target=ids[i];Button b=button(names[i],false,()->{screen=target;home();});b.setTextSize(12);b.setPadding(0,dp(8),0,dp(8));if(screen.equals(target)){b.setTextColor(0xff169ace);b.setBackground(bg(0xffddf4ff,0xff84d8ff,10));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(52),1);p.setMargins(dp(2),0,dp(2),0);nav.addView(b,p);}add(root,nav);}
 void home()throws Exception{inQuiz=false;shell();scrollBody();if(screen.equals("learn"))path();else if(screen.equals("review"))review();else if(screen.equals("bank"))library();else settings();navigation();}
 void path()throws Exception{
  LinearLayout hero=column();hero.setPadding(dp(20),dp(16),dp(20),dp(16));hero.setBackground(bg(GREEN,GREEN,16));TextView top=text("SECTION 1 · MIDTERM 1",12,true);top.setTextColor(Color.WHITE);add(hero,top);TextView title=text("Aerospace Technology",27,true);title.setTextColor(Color.WHITE);add(hero,title);spaced(body,hero);
  if(engine.session()!=null)spaced(body,button("Resume lesson",true,()->quiz()));
  for(int u=0;u<units.length;u++){TextView head=text("Unit "+(u+1)+" · "+units[u][1],19,true);head.setPadding(0,dp(30),0,dp(10));add(body,head);int pos=0;for(int i=0;i<engine.nodes.length();i++){JSONObject node=engine.nodes.getJSONObject(i);if(!node.getString("topic").equals(units[u][0]))continue;LinearLayout line=row();int[] shifts={0,14,28,14};line.setPadding(dp(shifts[pos++%4]),dp(12),0,dp(12));RingView ring=new RingView(node);ring.setContentDescription("Start "+node.getString("name"));ring.setOnClickListener(v->attempt(()->{JSONObject lesson=engine.nextLesson(node);engine.start(engine.strings(lesson.getJSONArray("ids")),lesson.getString("name"),"pathlesson",lesson.getString("id"));quiz();}));line.addView(ring,new LinearLayout.LayoutParams(dp(116),dp(116)));TextView label=text(node.getString("name"),16,true);label.setPadding(dp(12),0,0,0);line.addView(label,new LinearLayout.LayoutParams(0,-2,1));add(body,line);}}
 }
 final class RingView extends View{
  final JSONObject node;final Paint p=new Paint(3);RingView(JSONObject n){super(MainActivity.this);node=n;setFocusable(true);setClickable(true);}
  @Override protected void onDraw(Canvas c){super.onDraw(c);float scale=Math.min(getWidth(),getHeight())/124f;c.save();c.translate((getWidth()-124*scale)/2,(getHeight()-124*scale)/2);c.scale(scale,scale);try{JSONArray ls=node.getJSONArray("lessons");p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(8);p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<ls.length();i++){p.setColor(engine.done(ls.getJSONObject(i))?GREEN:GREY);if(ls.length()==1)c.drawCircle(62,62,51,p);else c.drawArc(new RectF(11,11,113,113),-90+i*360f/ls.length()+8,360f/ls.length()-16,false,p);}p.setStyle(Paint.Style.FILL);p.setColor(0xff58a700);c.drawCircle(62,62,39,p);p.setColor(isPressed()?0xff85d23d:0xff7ac932);c.drawOval(new RectF(23,23,101,95),p);Path star=new Path();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float r=i%2==0?20:10.5f,x=62+(float)Math.cos(a)*r,y=59+(float)Math.sin(a)*r;if(i==0)star.moveTo(x,y);else star.lineTo(x,y);}star.close();p.setColor(Color.WHITE);p.setPathEffect(new CornerPathEffect(3));c.drawPath(star,p);p.setPathEffect(null);}catch(Exception ignored){}c.restore();}
 }
 void review()throws Exception{add(body,text("Review mistakes",28,true));List<String> ids=engine.mistakes();if(ids.isEmpty()){add(body,text("All caught up!",22,true));add(body,text("Unresolved lesson mistakes will appear here until corrected.",16,false));return;}spaced(body,button("Review mistakes ("+ids.size()+")",true,()->{engine.start(ids,"Review mistakes","review","");quiz();}));for(String id:ids){JSONObject q=engine.questions.get(id);spaced(body,button(stars(q)+"  "+q.getString("stem"),false,()->{engine.start(Collections.singletonList(id),"Previous mistake","review","");quiz();}));}}
 String stars(JSONObject q){int d=q.optInt("difficulty");return d==3?"★★★":d==2?"★★☆":"★☆☆";}
 void library()throws Exception{
  add(body,text("Questions",28,true));LinearLayout filters=row();Spinner levels=spinner(new String[]{"All levels","★","★★","★★★"},difficulty),sources=spinner(new String[]{"All sources","Past exams","Think at home","Practice"},origin),years=spinner(new String[]{"All years","2019","2021","2022","2023","2025"},year);filters.addView(levels,new LinearLayout.LayoutParams(0,dp(52),1));filters.addView(sources,new LinearLayout.LayoutParams(0,dp(52),1));filters.addView(years,new LinearLayout.LayoutParams(0,dp(52),1));add(body,filters);
  EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Search questions");input.setText(search);add(body,input);LinearLayout list=column();add(body,list);
  Runnable refresh=()->attempt(()->{difficulty=String.valueOf(levels.getSelectedItem());origin=String.valueOf(sources.getSelectedItem());year=String.valueOf(years.getSelectedItem());search=input.getText().toString();fillLibrary(list);});
  AdapterView.OnItemSelectedListener listener=new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){shown=100;refresh.run();}public void onNothingSelected(AdapterView<?> p){}};levels.setOnItemSelectedListener(listener);sources.setOnItemSelectedListener(listener);years.setOnItemSelectedListener(listener);
  input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){shown=100;refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();
 }
 Spinner spinner(String[] values,String selected){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,values);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);for(int i=0;i<values.length;i++)if(values[i].equals(selected))s.setSelection(i);return s;}
 void fillLibrary(LinearLayout list)throws Exception{list.removeAllViews();List<String> ids=new ArrayList<>();String kind=origin.equals("Past exams")?"exam":origin.equals("Think at home")?"reflection":origin.equals("Practice")?"practice":"";for(JSONObject q:engine.questions.values()){JSONObject o=q.getJSONObject("origin");if(!difficulty.equals("All levels")&&q.getInt("difficulty")!=difficulty.length())continue;if(!kind.isEmpty()&&!o.optString("kind").equals(kind))continue;if(!year.equals("All years")&&!o.optString("date").startsWith(year))continue;if(!(q.getString("stem")+o.optString("title")).toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;ids.add(q.getString("id"));}
  add(list,text(ids.size()+" questions",14,false));if(!ids.isEmpty())spaced(list,button("Practise selection",true,()->{engine.start(ids,"Question practice","practice","");quiz();}));for(int i=0;i<Math.min(shown,ids.size());i++){String id=ids.get(i);JSONObject q=engine.questions.get(id),o=q.getJSONObject("origin");String caption=stars(q)+(o.optString("kind").equals("exam")?" · EXAM QUESTION\n"+o.optString("date")+" · Q"+o.optString("number")+"\n":"\n")+q.getString("stem");spaced(list,button(caption,false,()->{engine.start(Collections.singletonList(id),"Question practice","practice","");quiz();}));}if(shown<ids.size())spaced(list,button("Show more",false,()->{shown+=100;fillLibrary(list);}));
 }
 void settings()throws Exception{add(body,text("Settings",28,true));for(String key:new String[]{"sound","haptics","motion"}){Switch toggle=new Switch(this);toggle.setText(key.equals("sound")?"Lesson sounds":key.equals("haptics")?"Haptic feedback":"Animations");toggle.setTextSize(18);toggle.setPadding(0,dp(16),0,dp(16));toggle.setChecked(engine.settings().optBoolean(key,true));toggle.setOnCheckedChangeListener((v,on)->attempt(()->{engine.settings().put(key,on);engine.save();}));add(body,toggle);}add(body,text("Progress is saved automatically on this device.",16,false));add(body,text("DuoAero 1.0.0\n1,200 questions · Midterm 1",14,false));spaced(body,button("Sources and reference assets",false,()->new AlertDialog.Builder(this).setTitle("Sources and reference assets").setMessage("Each question contains its source and exam attribution. Answers are derived where the official key was not retained.\n\nSelected layout code, fonts, icons, sounds and transitions are adapted from the APK supplied by you. The course engine and local progress system are implemented for DuoAero.\n\n2022 Q13 retains the original excerpt; its unrecoverable measured stall angle is not fabricated.").setPositiveButton("OK",null).show()));}
 void quiz()throws Exception{inQuiz=true;
  if(engine.session()==null){home();return;}if(engine.ended()){completion();return;}
  shell();View layout=getLayoutInflater().inflate(R.layout.activity_session,root,false);root.addView(layout,new LinearLayout.LayoutParams(-1,-1));body=layout.findViewById(R.id.element_container);footer=layout.findViewById(R.id.feedback);layout.findViewById(R.id.quitButton).setOnClickListener(v->attempt(()->{engine.save();screen="learn";home();}));JSONObject s=engine.session(),q=engine.current();JSONArray order=engine.order(q);ProgressBar progress=layout.findViewById(R.id.progress);progress.setProgress(s.getJSONArray("awarded").length()*100/s.getJSONArray("ids").length());boolean retry=s.getInt("cursor")>=s.getJSONArray("ids").length()||s.getString("kind").equals("review"),checked=s.optBoolean("checked");JSONObject source=q.getJSONObject("origin");
  LinearLayout labels=row();if(source.optString("kind").equals("exam")){ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.hard_exercise);labels.addView(icon,new LinearLayout.LayoutParams(dp(24),dp(24)));TextView exam=text("  EXAM QUESTION",14,true);exam.setTextColor(PURPLE);labels.addView(exam);}else if(source.optString("kind").equals("reflection"))labels.addView(text("THINK AT HOME",14,true));TextView star=text(stars(q),18,true);star.setTextColor(0xffe8ac00);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);star.setGravity(Gravity.END);labels.addView(star,sp);add(body,labels);if(retry){TextView tag=text("↻ PREVIOUS MISTAKE",14,true);tag.setTextColor(PURPLE);add(body,tag);}add(body,text(q.getString("stem"),22,true));String type=q.getString("type");add(body,text(type.equals("multi")?"Select all correct answers.":type.equals("gap")?"Complete with one word.":type.equals("order")?"Put the steps in order.":type.equals("matching")?"Match every pair.":"Choose one answer.",15,false));
  Button check=button(checked?"CONTINUE":"CHECK",true,()->{if(engine.session().optBoolean("checked")){engine.advance();quiz();}else if(engine.check()){boolean ok=engine.session().optBoolean("correct");int combo=engine.session().optInt("combo");play(ok?(combo>0&&combo%10==0?"combo10":combo>0&&combo%5==0?"combo5":"correct"):"wrong");haptic(ok);quiz();}});
  if(type.equals("choice")||type.equals("multi")){for(int j=0;j<order.length();j++){final int i=order.getInt(j);boolean selected=type.equals("choice")?s.optInt("answer",-1)==i:contains(s.optJSONArray("answer"),i),correct=type.equals("choice")?q.getInt("answer")==i:contains(q.getJSONArray("answer"),i);Button option=button((type.equals("multi")?(selected?"☑  ":"☐  "):"")+q.getJSONArray("options").getString(i),false,()->{if(type.equals("choice"))engine.select(i);else{JSONArray a=engine.session().optJSONArray("answer"),n=new JSONArray();boolean had=contains(a,i);for(int k=0;a!=null&&k<a.length();k++)if(a.getInt(k)!=i)n.put(a.getInt(k));if(!had)n.put(i);engine.select(n);}quiz();});option.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);option.setTypeface(regular);option.setEnabled(!checked);if(checked&&correct)option.setBackground(bg(0xffd7ffb8,0xffa5ed6e,14));else if(checked&&selected)option.setBackground(bg(0xffffdfe0,0xffffb2b2,14));else if(selected)option.setBackground(bg(0xffddf4ff,0xff84d8ff,14));spaced(body,option);}}
  else if(type.equals("gap")){EditText input=new EditText(this);input.setSingleLine(true);input.setText(s.optString("answer",""));input.setEnabled(!checked);input.setHint("Missing word");input.setTypeface(regular);add(body,input);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence a,int b,int c,int d){}public void onTextChanged(CharSequence a,int b,int c,int d){attempt(()->{engine.select(a.toString());check.setEnabled(engine.ready(q,engine.session().opt("answer")));});}public void afterTextChanged(Editable a){}});}
  else if(type.equals("order")){if(!s.has("answer"))s.put("answer",new JSONArray(order.toString()));JSONArray a=s.getJSONArray("answer");for(int j=0;j<a.length();j++){final int pos=j;LinearLayout line=row();TextView item=text((j+1)+". "+q.getJSONArray("items").getString(a.getInt(j)),16,false);line.addView(item,new LinearLayout.LayoutParams(0,-2,1));for(int delta:new int[]{-1,1}){Button move=button(delta<0?"↑":"↓",false,()->{JSONArray ar=engine.session().getJSONArray("answer");int temp=ar.getInt(pos);ar.put(pos,ar.getInt(pos+delta));ar.put(pos+delta,temp);engine.select(ar);quiz();});move.setContentDescription("Move step "+(j+1)+(delta<0?" up":" down"));move.setEnabled(!checked&&pos+delta>=0&&pos+delta<a.length());line.addView(move,new LinearLayout.LayoutParams(dp(48),dp(52)));}spaced(body,line);}}
  else if(type.equals("matching")){JSONArray pairs=q.getJSONArray("pairs");if(!s.has("answer")){JSONArray initial=new JSONArray();for(int i=0;i<pairs.length();i++)initial.put(-1);s.put("answer",initial);}for(int j=0;j<pairs.length();j++){final int pos=j;add(body,text(pairs.getJSONArray(j).getString(0),16,true));String[] labelsArr=new String[order.length()+1];labelsArr[0]="Choose a match";int selection=0;for(int k=0;k<order.length();k++){labelsArr[k+1]=pairs.getJSONArray(order.getInt(k)).getString(1);if(s.getJSONArray("answer").optInt(j,-1)==order.getInt(k))selection=k+1;}Spinner match=spinner(labelsArr,labelsArr[selection]);match.setEnabled(!checked);add(body,match);match.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int selected,long id){if(checked)return;attempt(()->{JSONArray a=engine.session().getJSONArray("answer");a.put(pos,selected==0?-1:order.getInt(selected-1));engine.select(a);check.setEnabled(engine.ready(q,a));});}});}}
  String attribution=source.optString("kind").equals("exam")?"Exam: "+source.optString("date")+" · Model "+source.optString("model")+" · Question "+source.optString("number"):source.optString("kind").equals("reflection")?"Think at home · Slide "+source.optString("slide"):"Practice · Course material";add(body,text(attribution,13,true));if(source.optBoolean("adapted"))add(body,text("Translated or adapted for practice. Original wording below.",13,false));spaced(body,button("Source and original wording",false,()->new AlertDialog.Builder(this).setTitle(source.optString("title")).setMessage(source.optString("answer_basis","")+"\n\n"+source.optString("source_excerpt",q.optString("explanation"))).setPositiveButton("Open source",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(source.optString("url"))));}catch(Exception ignored){}}).setNegativeButton("Close",null).show()));
  if(checked){boolean ok=s.optBoolean("correct");footer.setBackgroundColor(ok?0xffd7ffb8:0xffffdfe0);add(footer,text(ok?(retry?"Mistake corrected!":"Nicely done!"):"Let's learn from this",20,true));ScrollView feedbackScroll=new ScrollView(this);LinearLayout explanation=column();if(!ok)add(explanation,text("Correct answer: "+engine.solution(q),15,true));add(explanation,text(q.getString("explanation"),15,false));feedbackScroll.addView(explanation);footer.addView(feedbackScroll,new LinearLayout.LayoutParams(-1,dp(110)));JSONObject explanations=q.optJSONObject("option_explanations");if(explanations!=null)spaced(body,button("Why the alternatives differ",false,()->{StringBuilder t=new StringBuilder();JSONArray options=q.getJSONArray("options");for(int i=0;i<options.length();i++){String option=options.getString(i);t.append(option).append("\n").append(explanations.optString(option,explanations.optString(String.valueOf((char)('A'+i)),q.optString("explanation")))).append("\n\n");}new AlertDialog.Builder(this).setTitle("Answer explanations").setMessage(t.toString()).setPositiveButton("OK",null).show();}));if(motion())footer.startAnimation(AnimationUtils.loadAnimation(this,R.anim.adventures_slide_in_bottom));}
  check.setEnabled(checked||engine.ready(q,s.opt("answer")));add(footer,check);engine.save();
 }
 boolean contains(JSONArray a,int v){for(int i=0;a!=null&&i<a.length();i++)if(a.optInt(i,-1)==v)return true;return false;}
 void completion()throws Exception{shell();scrollBody();body.setGravity(Gravity.CENTER);JSONObject s=engine.session();int first=0;Iterator<String> it=s.getJSONObject("initialResults").keys();while(it.hasNext())if(s.getJSONObject("initialResults").optBoolean(it.next()))first++;int total=s.getJSONArray("ids").length();boolean perfect=first==total;TextView trophy=text("★",100,true);trophy.setTextColor(0xffffc800);trophy.setGravity(Gravity.CENTER);add(body,trophy);TextView title=text(perfect?"Perfect lesson!":"Lesson complete!",30,true);title.setGravity(Gravity.CENTER);add(body,title);TextView stats=text(Math.round(100f*first/total)+"% first-pass accuracy\n"+total+" questions corrected\n"+(s.getJSONArray("queue").length()-total)+" retries",20,false);stats.setGravity(Gravity.CENTER);spaced(body,stats);spaced(body,button("CONTINUE",true,()->{engine.leave();screen="learn";home();}));spaced(body,button("Review remaining mistakes ("+engine.mistakes().size()+")",false,()->{engine.leave();screen="review";home();}));if(!s.optBoolean("celebrated")){s.put("celebrated",true);engine.save();play(perfect?"perfect":"complete");haptic(true);if(motion())body.startAnimation(AnimationUtils.loadAnimation(this,R.anim.adventures_slide_in_bottom));}}
 boolean motion(){return engine.settings().optBoolean("motion",true)&&Settings.Global.getFloat(getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1f)>0;}
 void play(String name){if(!engine.settings().optBoolean("sound",true))return;try{if(player!=null){player.release();player=null;}android.content.res.AssetFileDescriptor a=getAssets().openFd("audio/"+name+".mp3");player=new MediaPlayer();player.setDataSource(a.getFileDescriptor(),a.getStartOffset(),a.getLength());a.close();player.setVolume(.65f,.65f);player.prepare();player.setOnCompletionListener(p->{p.release();if(player==p)player=null;});player.start();}catch(Exception ignored){}}
 void haptic(boolean correct){if(!engine.settings().optBoolean("haptics",true))return;try{Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null&&v.hasVibrator())v.vibrate(VibrationEffect.createWaveform(correct?new long[]{0,35}:new long[]{0,70,50,70},-1));}catch(Exception ignored){}}
 @Override public void onBackPressed(){attempt(()->{if(inQuiz){engine.save();screen="learn";home();}else if(!screen.equals("learn")){screen="learn";home();}else super.onBackPressed();});}
 @Override protected void onPause(){super.onPause();if(engine!=null)try{engine.save();}catch(Exception ignored){}}
 @Override protected void onDestroy(){if(player!=null){player.release();player=null;}super.onDestroy();}
}
